<?php require __DIR__.'/../lib.php'; require_login(); $db=db(); $apps=$db->query("SELECT * FROM apps ORDER BY sort_order,id DESC")->fetchAll(); $inq=$db->query("SELECT * FROM inquiries ORDER BY created_at DESC")->fetchAll(); $statusLabels=['entwicklung'=>'In Entwicklung','bald_verfuegbar'=>'Bald verfügbar','google'=>'Google Play','apple'=>'Apple App Store','both'=>'Google Play & Apple App Store']; $categories=project_categories(); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin – Gering Digital</title><link rel="stylesheet" href="../style.css"><style><?php include __DIR__.'/admin.css'; ?></style></head><body class="admin-page"><header class="nav"><div class="wrap navin"><a class="brand" href="../index.php"><strong>Gering</strong> <span>Digital</span><small>ADMIN</small></a><a class="btn" href="../index.php">← Zurück</a></div></header><main class="admin"><div class="wrap"><div class="adminbar"><div><p class="eyebrow">ADMINISTRATION</p><h1>Dashboard</h1></div><a class="btn" href="html_projects.php">⌘ HTML-Projekte verwalten →</a></div>
<section class="panel"><h2>App hinzufügen</h2><form method="post" action="save_app.php" enctype="multipart/form-data" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Name *<input name="name" required></label><label>Kurzbeschreibung *<textarea name="short_description" required rows="3"></textarea></label><label>Kategorie<select name="category" required><?php foreach($categories as $key=>$label): ?><option value="<?=e($key)?>"><?=e($label)?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Status<select name="status"><option value="entwicklung">In Entwicklung</option><option value="bald_verfuegbar" selected>Bald verfügbar</option><option value="google">Veröffentlicht – Google Play</option><option value="apple">Veröffentlicht – Apple App Store</option><option value="both">Veröffentlicht – Google Play & Apple App Store</option></select></label><label>Reihenfolge<input name="sort_order" type="number" value="0"></label></div><label>Google-Play-Link<input name="play_url" type="url"></label><label>Apple-App-Store-Link<input name="apple_url" type="url"></label><label>Icon (JPG/PNG/WebP)<input name="icon" type="file" accept=".jpg,.jpeg,.png,.webp"></label><label class="check"><input type="checkbox" name="published" value="1" checked> Auf der öffentlichen Website anzeigen</label><button class="btn">Projekt speichern</button></form></section>
<section class="panel"><div class="panel-heading-row"><div><h2>Meine Projekte</h2><p class="admin-hint">Ziehe die Apps per Drag &amp; Drop in die gewünschte Reihenfolge oder nutze ↑ / ↓. Danach auf „Reihenfolge speichern“ klicken.</p></div><button type="button" class="btn" id="save-order">Reihenfolge speichern</button></div><div id="order-message" class="order-message" aria-live="polite"></div><div class="app-order-list" id="app-order-list"><?php foreach($apps as $a): $st=$a['status']??($a['play_url']?'google':'bald_verfuegbar'); ?><div class="app-order-item" draggable="true" data-id="<?=$a['id']?>"><div class="drag-handle" title="Ziehen zum Verschieben" aria-label="Ziehen zum Verschieben">⠿</div><div class="app-order-main"><strong><?=e($a['name'])?></strong><small><?=e($categories[$a['category']??'apps']??'Apps')?> · <?=e($a['short_description'])?></small></div><span class="status <?=in_array($st,['google','apple','both'],true)?'live':($st==='bald_verfuegbar'?'soon':'dev')?>"><?=e($statusLabels[$st]??$st)?></span><div class="order-actions"><button type="button" class="order-btn move-up" title="Nach oben" aria-label="Nach oben">↑</button><button type="button" class="order-btn move-down" title="Nach unten" aria-label="Nach unten">↓</button><a href="edit_app.php?id=<?=$a['id']?>" class="order-edit">Bearbeiten</a><a class="danger" href="delete_app.php?id=<?=$a['id']?>&csrf=<?=e(csrf())?>" onclick="return confirm('App wirklich löschen?')">Löschen</a></div></div><?php endforeach; ?></div></section><script>const list=document.getElementById('app-order-list');let dragged=null;list.querySelectorAll('.app-order-item').forEach(item=>{item.addEventListener('dragstart',()=>{dragged=item;item.classList.add('dragging')});item.addEventListener('dragend',()=>{item.classList.remove('dragging');dragged=null});item.addEventListener('dragover',e=>{e.preventDefault();if(!dragged||dragged===item)return;const r=item.getBoundingClientRect();const before=e.clientY<r.top+r.height/2;list.insertBefore(dragged,before?item:item.nextSibling)});});list.addEventListener('click',e=>{const b=e.target.closest('.order-btn');if(!b)return;const item=b.closest('.app-order-item');if(b.classList.contains('move-up')){const prev=item.previousElementSibling;if(prev)list.insertBefore(item,prev)}else{const next=item.nextElementSibling;if(next)list.insertBefore(next,item)}});document.getElementById('save-order').addEventListener('click',async()=>{const ids=[...list.querySelectorAll('.app-order-item')].map(x=>x.dataset.id);const msg=document.getElementById('order-message');const fd=new FormData();fd.append('csrf','<?=e(csrf())?>');ids.forEach(id=>fd.append('order[]',id));try{const r=await fetch('reorder_apps.php',{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}});const j=await r.json();msg.textContent=j.message||'Reihenfolge gespeichert.';msg.className='order-message '+(j.ok?'ok':'error')}catch(e){msg.textContent='Speichern fehlgeschlagen.';msg.className='order-message error'}});</script>
<section class="panel"><h2>Kundenanfragen <span class="pill"><?=count($inq)?></span></h2><?php if(!$inq): ?><p>Noch keine Anfragen.</p><?php else: ?><table><tr><th>Datum</th><th>Name / E-Mail</th><th>Betreff</th><th>Nachricht</th></tr><?php foreach($inq as $i): ?><tr><td><?=e($i['created_at'])?></td><td><?=e($i['name'])?><br><a href="mailto:<?=e($i['email'])?>"><?=e($i['email'])?></a></td><td><?=e($i['subject'])?></td><td><?=nl2br(e($i['message']))?></td></tr><?php endforeach; ?></table><?php endif; ?></section>
